   466	{
   467	        FLAC__uint32 hi, lo;
   468	
   469	        if(bits > 32) {
   470	                if(!FLAC__bitreader_read_raw_uint32(br, &hi, bits-32))
   471	                        return false;
   472	                if(!FLAC__bitreader_read_raw_uint32(br, &lo, 32))
   473	                        return false;
   474	                *val = hi;
   475	                *val <<= 32;
   476	                *val |= lo;
   477	        }
   478	        else {
   479	                if(!FLAC__bitreader_read_raw_uint32(br, &lo, bits))
   480	                        return false;
   481	                *val = lo;
   482	        }
   483	        return true;
